// SpacetimeDB adapter (spacetimedb@2.13.0) implementing RealtimeBackend.
//
// `../module_bindings` is GENERATED by `pnpm --filter @prevent/realtime gen`
// (spacetime generate --lang typescript) and is gitignored. This file will not typecheck until
// the module has been published once and bindings generated.
//
// React UIs (dashboard + 2D sim) should NOT use this adapter's subscribe(); use the shipped hooks:
//
//   import { SpacetimeDBProvider, useTable, useReducer } from 'spacetimedb/react';
//   import { tables, reducers } from '@prevent/realtime/module_bindings'; // or relative path
//   import { createSpacetimeBuilder } from '@prevent/realtime/backend';
//
//   <SpacetimeDBProvider connectionBuilder={createSpacetimeBuilder(cfg)}>  // do NOT call .build()
//     ...
//   const [rows, isReady] = useTable(tables.deviceStatus);
//   const approve = useReducer(reducers.approvePatch);
//
// (Prop name `connectionBuilder` per the react-ts template; confirm against the generated
//  template's main.tsx.) Non-React processes (serial bridge, agents, emulator) use this adapter.
//
// Accessor names are camelCase of the table names (deviceStatus, agentStatus, exploitRuns, ...),
// and reducer args are passed as a single object.

import type {
  AgentStatus,
  DeviceStatus,
  EventLogRow,
  ExploitRun,
  Finding,
  IrEvent,
  PatchAttempt,
} from '@prevent/contracts';
import { DbConnection, tables } from '../module_bindings';
import type {
  RealtimeBackend,
  RecordExploitRunArgs,
  RecordFindingArgs,
  RecordPatchAttemptArgs,
  TableMap,
  TableName,
  Unsubscribe,
  UpdateAgentStatusArgs,
  UpdateDeviceStatusArgs,
} from './RealtimeBackend';

export interface SpacetimeConfig {
  /** e.g. ws://localhost:3000 (local) or wss://maincloud.spacetimedb.com */
  uri: string;
  /** Database name the module was published under (VITE_SPACETIMEDB_MODULE), e.g. "prevent". */
  moduleName: string;
  /**
   * Auth token for this process. Role checks in the module key off the resulting identity, so
   * services must keep a stable token (persisted below) and be granted their role once.
   * TODO(dev): for the serial bridge / agents read from process.env.SPACETIMEDB_TOKEN.
   */
  token?: string;
}

// Table name -> generated accessor (client `conn.db.<accessor>` and `tables.<accessor>`).
const ACCESSOR = {
  device_status: 'deviceStatus',
  agent_status: 'agentStatus',
  findings: 'findings',
  exploit_runs: 'exploitRuns',
  patch_attempts: 'patchAttempts',
  event_log: 'eventLog',
  ir_events: 'irEvents',
} as const satisfies Record<TableName, string>;

// ---- row mappers: generated row -> contract shape ------------------------------------------
// Numeric columns are u32/f64 so they arrive as plain `number` (no bigint). Option<f64> arrives
// as `number | undefined`; the contract wants `number | null`.
/* eslint-disable @typescript-eslint/no-explicit-any */
const MAP: { [K in TableName]: (r: any) => TableMap[K] } = {
  device_status: (r): DeviceStatus => ({
    id: 1,
    fanOn: r.fanOn,
    trueHr: r.trueHr,
    trueSpo2: r.trueSpo2,
    reportedHr: r.reportedHr,
    reportedSpo2: r.reportedSpo2,
    alarmActive: r.alarmActive,
    compromised: r.compromised,
    lastCommand: r.lastCommand,
    updatedAt: r.updatedAt,
  }),
  agent_status: (r): AgentStatus => ({
    id: r.id,
    agentName: r.agentName,
    stage: r.stage,
    state: r.state,
    reasoning: r.reasoning,
    confidence: r.confidence,
    uncertainty: r.uncertainty,
    updatedAt: r.updatedAt,
  }),
  findings: (r): Finding => ({
    id: r.id,
    scanner: r.scanner,
    cveRef: r.cveRef,
    file: r.file,
    line: r.line,
    severity: r.severity,
    claudeVerdict: r.claudeVerdict,
    isTheRealOne: r.isTheRealOne,
    createdAt: r.createdAt,
  }),
  exploit_runs: (r): ExploitRun => ({
    id: r.id,
    findingId: r.findingId,
    modelId: r.modelId,
    payloadRef: r.payloadRef,
    deliveredAt: r.deliveredAt,
    deviceImpact: r.deviceImpact,
    success: r.success,
  }),
  patch_attempts: (r): PatchAttempt => ({
    id: r.id,
    findingId: r.findingId,
    diffRef: r.diffRef,
    droidSession: r.droidSession,
    proposedAt: r.proposedAt,
    humanApproved: r.humanApproved,
    appliedAt: r.appliedAt ?? null,
  }),
  event_log: (r): EventLogRow => ({ id: r.id, ts: r.ts, actor: r.actor, text: r.text }),
  ir_events: (r): IrEvent => ({ id: r.id, ts: r.ts, code: r.code, consumed: r.consumed }),
};

/**
 * Build (but do NOT .build()) the connection builder. SpacetimeDBProvider takes the builder
 * as-is; SpacetimeBackend calls .build() itself.
 */
export function createSpacetimeBuilder(cfg: SpacetimeConfig) {
  const tokenKey = `${cfg.uri}/${cfg.moduleName}/auth_token`;
  const store = typeof localStorage !== 'undefined' ? localStorage : undefined;
  const token = cfg.token ?? safeGet(store, tokenKey);
  return DbConnection.builder()
    .withUri(cfg.uri)
    .withDatabaseName(cfg.moduleName)
    .withToken(token)
    .withAutomaticReconnect()
    .onConnect((_conn, identity, newToken) => {
      safeSet(store, tokenKey, newToken);
      console.log('[realtime] connected as', identity.toHexString());
    });
}

function safeGet(s: Storage | undefined, k: string): string | undefined {
  try {
    return s?.getItem(k) ?? undefined;
  } catch {
    return undefined;
  }
}
function safeSet(s: Storage | undefined, k: string, v: string): void {
  try {
    s?.setItem(k, v);
  } catch {
    /* storage unavailable - identity will rotate on next load */
  }
}

export class SpacetimeBackend implements RealtimeBackend {
  readonly kind = 'spacetimedb' as const;
  private conn: ReturnType<ReturnType<typeof createSpacetimeBuilder>['build']> | null = null;
  private applied = false;
  private listeners = new Map<TableName, Set<(rows: never[]) => void>>();

  constructor(private readonly cfg: SpacetimeConfig) {}

  connect(): Promise<void> {
    return new Promise<void>((resolve, reject) => {
      const builder = createSpacetimeBuilder(this.cfg).onConnectError((_ctx, err) => reject(err));
      const conn = builder.build();
      this.conn = conn;

      // Row callbacks: register once; the SDK replays them after an automatic reconnect.
      for (const name of Object.keys(ACCESSOR) as TableName[]) {
        const handle = (conn.db as any)[ACCESSOR[name]];
        const fire = () => this.emit(name);
        handle.onInsert(fire);
        handle.onDelete(fire);
        if (handle.onUpdate) handle.onUpdate(fire); // only tables with a primary key (all of ours)
      }

      conn
        .subscriptionBuilder()
        .onApplied(() => {
          this.applied = true;
          (Object.keys(ACCESSOR) as TableName[]).forEach((n) => this.emit(n));
          resolve();
        })
        .onError((_ctx: unknown) => reject(new Error('SpacetimeDB subscription error')))
        .subscribe(Object.values(ACCESSOR).map((a) => (tables as any)[a]));
    });
  }

  disconnect(): void {
    this.conn?.disconnect();
    this.conn = null;
    this.applied = false;
  }

  subscribe<K extends TableName>(table: K, cb: (rows: TableMap[K][]) => void): Unsubscribe {
    let set = this.listeners.get(table);
    if (!set) {
      set = new Set();
      this.listeners.set(table, set);
    }
    const listener = cb as unknown as (rows: never[]) => void;
    set.add(listener);
    if (this.applied) cb(this.read(table)); // late subscriber gets the current snapshot
    return () => {
      set.delete(listener);
    };
  }

  private read<K extends TableName>(table: K): TableMap[K][] {
    if (!this.conn) return [];
    const handle = (this.conn.db as any)[ACCESSOR[table]];
    const out: TableMap[K][] = [];
    for (const row of handle.iter()) out.push(MAP[table](row));
    return out;
  }

  private emit(table: TableName): void {
    if (!this.applied) return; // wait for the initial snapshot
    const set = this.listeners.get(table);
    if (!set?.size) return;
    const rows = this.read(table) as never[];
    set.forEach((cb) => cb(rows));
  }

  // ---- reducers -------------------------------------------------------------------------------
  // Generated reducer methods take ONE args object. TODO(dev): verify whether they return a
  // Promise in 2.13 (spacetimedb/react useReducer yields an async fn); Promise.resolve() covers both.
  private get r(): any {
    if (!this.conn) throw new Error('SpacetimeBackend: not connected');
    return this.conn.reducers;
  }

  async updateDeviceStatus(a: UpdateDeviceStatusArgs): Promise<void> {
    await Promise.resolve(this.r.updateDeviceStatus(a));
  }
  async updateAgentStatus(a: UpdateAgentStatusArgs): Promise<void> {
    await Promise.resolve(this.r.updateAgentStatus(a));
  }
  async recordFinding(a: RecordFindingArgs): Promise<void> {
    await Promise.resolve(this.r.recordFinding(a));
  }
  async recordExploitRun(a: RecordExploitRunArgs): Promise<void> {
    await Promise.resolve(this.r.recordExploitRun(a));
  }
  async recordPatchAttempt(a: RecordPatchAttemptArgs): Promise<void> {
    // t.option(...) args take undefined for "none".
    await Promise.resolve(
      this.r.recordPatchAttempt({
        patchId: a.patchId,
        findingId: a.findingId,
        diffRef: a.diffRef,
        droidSession: a.droidSession,
        appliedAt: a.appliedAt ?? undefined,
      })
    );
  }
  async approvePatch(patchId: number): Promise<void> {
    await Promise.resolve(this.r.approvePatch({ patchId }));
  }
  async logEvent(actor: string, text: string): Promise<void> {
    await Promise.resolve(this.r.logEvent({ actor, text }));
  }
  async pushIrEvent(code: number): Promise<void> {
    await Promise.resolve(this.r.pushIrEvent({ code }));
  }
  async resetHealthy(): Promise<void> {
    await Promise.resolve(this.r.resetHealthy());
  }
}
